package org.openidentity.samples.microsoftad;
import jakarta.servlet.http.HttpSession;import org.openidentity.ad.*;import org.openidentity.auth.*;import org.openidentity.core.*;import org.openidentity.spring.ad.*;import org.springframework.boot.*;import org.springframework.boot.autoconfigure.SpringBootApplication;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import java.security.SecureRandom;import java.util.*;

@SpringBootApplication @RestController
public class MicrosoftAdApplication {
 static final String PENDING="AD_BIND_PENDING";record Pending(VerifiedAdPrincipal p,ExternalAdBindingV1.Binding b,byte[] challenge,byte[] audience,byte[] nonce,byte[] contextHash){}
 private final InMemoryExternalAdBindingRegistry registry;private final InMemoryExternalAdBindingRegistry.Policy policy;private final FileCanonicalIdentityStateRepository states;private final Oi015Verifier verifier;
 public MicrosoftAdApplication(InMemoryExternalAdBindingRegistry r,InMemoryExternalAdBindingRegistry.Policy p,FileCanonicalIdentityStateRepository s){registry=r;policy=p;states=s;verifier=new Oi015Verifier(new CanonicalAuthenticationStateResolver(s),300);}
 public static void main(String[] a){SpringApplication.run(MicrosoftAdApplication.class,a);}
 @GetMapping("/") Map<String,Object> home(org.springframework.security.core.Authentication auth){
  var token=(OpenIdentityAdAuthenticationToken)auth;var r=token.result();var p=r.verifiedPrincipal();
  if(r.bound())return Map.of("status","AUTHENTICATED","identity",hex(r.openIdentityId()),"provider","MICROSOFT_ACTIVE_DIRECTORY","principal",r.kerberosPrincipal(),"principalResolution","LDAPS","authentication","KERBEROS_SPNEGO","productionAuthentication",true,"bindingStatus","ACTIVE","objectGuidLdapOctetsHex",hex(p.objectGuid()));
  return Map.of("status","MICROSOFT_AD_AUTHENTICATED","provider","MICROSOFT_ACTIVE_DIRECTORY","principal",r.kerberosPrincipal(),"principalResolution","LDAPS","authentication","KERBEROS_SPNEGO","productionAuthentication",true,"objectGuidLdapOctetsHex",hex(p.objectGuid()),"next","GET /openidentity/link/begin?identity=<64-hex OpenIdentity ID>");
 }
 @GetMapping("/openidentity/link/begin") Map<String,String> begin(@RequestParam String identity,org.springframework.security.core.Authentication auth,HttpSession s){
  var r=((OpenIdentityAdAuthenticationToken)auth).result();byte[] id=HexFormat.of().parseHex(identity);var st=states.resolve(id);if(id.length!=32||st==null)throw new IllegalArgumentException("identity");long gen=policy.currentAuthenticationGeneration(id),t=now();var p=r.verifiedPrincipal();var b=new ExternalAdBindingV1.Binding(id,p.directoryId(),p.objectGuid(),p.serviceId(),t,null,gen);byte[] ch=random(),aud=random(),nonce=random(),ctx=ExternalAdBindingV1.encodeContext(ExternalAdBindingV1.BIND,b,p.authenticationMechanism(),ch,null),hash=ExternalAdBindingV1.contextHash(ctx);s.setAttribute(PENDING,new Pending(p,b,ch,aud,nonce,hash));return Map.of("purpose","openidentity.external-ad.bind","stateHashHex",hex(st.stateHash()),"authenticationGeneration",Long.toString(gen),"audienceHex",hex(aud),"nonceHex",hex(nonce),"contextHashHex",hex(hash));
 }
 @PostMapping(value="/openidentity/link/complete",consumes="text/plain") Map<String,Object> complete(@RequestBody String body,HttpSession s){
  var p=(Pending)s.getAttribute(PENDING);if(p==null)throw new IllegalStateException("No pending Microsoft AD binding ceremony");var secured=Oi015Codec.decode(HexFormat.of().parseHex(body.trim()));var vr=verifier.tryVerify(secured,p.audience(),"openidentity.external-ad.bind",p.nonce(),p.contextHash(),now());if(!vr.valid())throw new ExternalAdBindingException(vr.contextMismatch()?ExternalAdBindingError.BINDING_CONTEXT_MISMATCH:ExternalAdBindingError.BINDING_AUTHORIZATION_INVALID);var rp=ExternalAdPrincipalBridge.registryPrincipal(p.p());var state=registry.bind(rp,p.b().identity(),p.b().createdAt(),p.b().expiresAt(),p.challenge(),new InMemoryExternalAdBindingRegistry.Authorization(true,"openidentity.external-ad.bind",true,false),policy);s.removeAttribute(PENDING);return Map.of("status","BOUND","identity",hex(p.b().identity()),"bindingId",hex(state.bindingId()),"provider","MICROSOFT_ACTIVE_DIRECTORY","productionAuthentication",true,"next","/");
 }
 private static byte[] random(){byte[] b=new byte[32];new SecureRandom().nextBytes(b);return b;}private static long now(){return System.currentTimeMillis()/1000;}private static String hex(byte[] b){return HexFormat.of().formatHex(b);}
}